with tempfile.TemporaryDirectory(prefix='fc-tagged-table-')as temp:
 source=pathlib.Path(temp)/'table-list.fodt';source.write_text(fodt);subprocess.run([os.environ.get('FC_SOFFICE','soffice'),'--headless','--convert-to','pdf:writer_pdf_Export:'+json.dumps({'UseTaggedPDF':{'type':'boolean','value':'true'}}),'--outdir',str(root),str(source)],check=True)
